import { useEffect, useRef, type RefObject } from "react";

/**
 * Moves keyboard / screen-reader focus to `ref` whenever `routeKey` changes
 * (e.g. on SPA navigation), so focus isn't stranded on the link that was
 * clicked or lost to an unmounted node. Skips the initial mount.
 *
 * Point it at a landmark -- typically `<main>` with `tabIndex={-1}` and
 * `outline-none` (it's a container, not a control, so it shouldn't show a focus
 * ring). Focus is set with `preventScroll` so navigation doesn't cause a jump.
 *
 * Router-agnostic: the caller supplies the route key (e.g. `location.pathname`).
 */
export function useRouteFocus(
  routeKey: unknown,
  ref: RefObject<HTMLElement | null>,
): void {
  const isFirstRender = useRef(true);
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    ref.current?.focus({ preventScroll: true });
  }, [routeKey, ref]);
}
